-- PixVerse — Генерація відео
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pixverse.ai' OR LOWER(`name`) = LOWER('PixVerse'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PixVerse', NULL, 'https://pixverse.ai', NULL, NULL, 'AI-платформа для створення відео з тексту чи зображення: власні моделі генерації, готові шаблони, синхронізація губ із голосом, сталі персонажі й окремий розділ для рекламних роликів.', 'An AI platform for creating video from text or an image: in-house generation models, ready-made templates, lip sync with voice, consistent characters and a dedicated section for ad videos.', 'PixVerse — сервіс для створення коротких відео за допомогою власних моделей генерації компанії. Достатньо описати сцену словами або завантажити зображення, і платформа перетворить це на відеокліп. Для тих, хто не хоче писати детальні підказки, є готові шаблони та розділ Marketing Hub, де за кілька кроків можна зробити рекламне відео для товару, наприклад із фото чи посилання на сторінку магазину. Окремий AI-агент дозволяє керувати створенням у форматі розмови: описати, що змінити в кадрі, і поступово доводити ролик до потрібного результату. Також доступні синхронізація губ персонажа з голосом і звуком, збереження одного й того самого персонажа в різних сценах, міні-застосунки для швидких завдань і полотно Canvas, де можна вибудувати весь процес виробництва відео як схему з блоків. Для розробників є API та інструмент командного рядка. Сервіс працює у браузері, також є мобільний застосунок.', 'PixVerse is a service for creating short videos with the company''s own generation models. Describe a scene in words or upload an image and the platform turns it into a video clip. If you don''t want to write detailed prompts, there are ready-made templates and the Marketing Hub, where you can make an ad video for a product in a few steps, for example from a photo or a store page link. A separate AI agent lets you direct the work as a conversation: describe what should change in the shot and refine the clip step by step. Lip sync with voice and sound, keeping the same character across scenes, quick mini-apps and the Canvas board, where the whole video production process can be built as a diagram of blocks, are also available. Developers get an API and a command-line tool. The service works in the browser and also has a mobile app.', 'Створення відео з текстового опису або зображення
Готові шаблони для швидкого старту
Marketing Hub для рекламних роликів товарів
AI-агент для керування відео через розмову
Синхронізація губ із голосом і звуком
Сталі персонажі в різних сценах
Полотно Canvas для побудови процесу з блоків
API та інструмент командного рядка', 'Video from a text description or an image
Ready-made templates for a quick start
Marketing Hub for product ad videos
AI agent to direct video through conversation
Lip sync with voice and sound
Consistent characters across scenes
Canvas board to build workflows from blocks
API and command-line tool', 'Автори контенту, маркетологи й інтернет-магазини, яким потрібні короткі відео та рекламні ролики без зйомок.', 'Content creators, marketers and online stores that need short videos and ads without filming.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
