-- Base44 — Веб-розробка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'base44.com' OR LOWER(`name`) = LOWER('Base44'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Base44', NULL, 'https://base44.com', NULL, NULL, 'Конструктор застосунків, сайтів та AI-агентів без коду: опишіть ідею словами, а Base44 збере готовий продукт із базою даних, входом користувачів, оплатами й хостингом, які вже вбудовані.', 'A no-code builder for apps, websites and AI agents: describe your idea in words and Base44 assembles a finished product with database, user sign-in, payments and hosting already built in.', 'Base44 дозволяє створювати застосунки, вебсайти, ігри, внутрішні інструменти й AI-агентів, просто описуючи бажаний результат звичайними словами. Технічну частину платформа бере на себе: база даних і сховище, вхід користувачів, прийом оплат і хостинг уже вбудовані, тому не потрібно налаштовувати сервер чи підключати платіжні системи окремо. Готовий проєкт можна запустити на власному домені, відстежувати аналітику відвідувань і змінювати дизайн — кольори та шрифти задаються в одному місці для всього застосунку, а AI може запропонувати кілька варіантів редизайну з попереднім переглядом. Є спільна дошка для командної роботи, генерація відео для сторінок і вбудовані маркетингові інструменти: панель SEO, яка показує, що виправити, щоб проєкт знаходили в Google і AI-пошуку, та допомога з присутністю в соцмережах. На платних тарифах доступні редагування коду, вибір AI-моделі та інтеграція з GitHub.', 'Base44 lets you build apps, websites, games, internal tools and AI agents simply by describing the result in plain words. The platform handles the technical side: database and storage, user sign-in, payments and hosting are built in, so there is no server to configure or payment provider to wire up separately. A finished project can go live on your own domain, track visitor analytics and change its design: colors and fonts are set in one place for the whole app, and AI can suggest several redesign options with a preview. There is a shared board for teamwork, video generation for pages and built-in marketing tools: an SEO panel that shows what to fix so the project is found in Google and AI search, and help with social media presence. Paid plans add code editing, AI model selection and GitHub integration.', 'Створення застосунків і сайтів за текстовим описом
Вбудовані база даних, вхід користувачів, оплати й хостинг
Створення AI-агентів, що працюють із вашими сервісами
Власний домен і аналітика
Керування дизайном і варіанти редизайну від AI
Панель SEO для пошуку в Google та AI-сервісах
Інтеграція з GitHub і редагування коду', 'Build apps and websites from a text description
Built-in database, user sign-in, payments and hosting
AI agents that work with your services
Custom domain and analytics
Design control and AI redesign options
SEO panel for Google and AI search
GitHub integration and code editing', 'Підприємці, фрилансери й команди без програмістів, які хочуть швидко запустити застосунок, сайт чи внутрішній інструмент.', 'Entrepreneurs, freelancers and teams without developers who want to launch an app, website or internal tool quickly.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
