INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Base44 lets you build apps, websites, games, internal tools and AI agents simply by describing the result in plain words. The platform handles the technical side: database and storage, user sign-in, payments and hosting are built in, so there is no server to configure or payment provider to wire up separately. A finished project can go live on your own domain, track visitor analytics and change its design: colors and fonts are set in one place for the whole app, and AI can suggest several redesign options with a preview. There is a shared board for teamwork, video generation for pages and built-in marketing tools: an SEO panel that shows what to fix so the project is found in Google and AI search, and help with social media presence. Paid plans add code editing, AI model selection and GitHub integration.', 'manual' FROM DUAL WHERE @new = 1;
