-- Floot — Веб-розробка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'floot.com' OR LOWER(`name`) = LOWER('Floot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Floot', NULL, 'https://floot.com', NULL, NULL, 'Сервіс, який підключається до Claude, ChatGPT чи Cursor і дозволяє зібрати повноцінний застосунок прямо в розмові з AI: база даних, акаунти користувачів, розсилки й публікація в веб і магазини застосунків.', 'A service that connects to Claude, ChatGPT or Cursor and lets you build a full app right in a chat with AI: database, user accounts, emails, and publishing to the web and app stores.', 'Floot працює як доповнення до AI-асистента, яким ви вже користуєтесь. Його підключають до Claude, ChatGPT або Cursor, після чого достатньо описати в чаті, який застосунок потрібен, і Floot збере його повністю — разом із базою даних, хостингом і власним посиланням. Не потрібні git, термінал чи окремі кредити на збірку. Застосунок може зберігати дані, дозволяти користувачам реєструватися, автоматично виконувати повторювані завдання за розкладом, надсилати листи, квитанції й сповіщення. Публікація відбувається в один клік — у вебі, а також в App Store і Google Play. SEO-налаштування додаються автоматично, щоб проєкт знаходили пошуковики, а підключення Stripe, входу через Google, Zapier та інших сервісів Floot проводить крок за кроком. Безкоштовний тариф дає змогу спробувати сервіс, платні додають більше дій на день, AI-кредити для функцій застосунку та хостинг.', 'Floot works as an add-on to the AI assistant you already use. You connect it to Claude, ChatGPT or Cursor, then describe in the chat what app you need, and Floot builds it completely, with a database, hosting and its own link. No git, terminal or separate build credits are needed. The app can store data, let users register, run recurring tasks on a schedule and send emails, receipts and notifications. Publishing takes one click: to the web, and to the App Store and Google Play. SEO settings are added automatically so search engines can find the project, and Floot walks you step by step through connecting Stripe, Google sign-in, Zapier and other services. The free plan lets you try the service; paid plans add more daily actions, AI credits for app features and hosting.', 'Підключення до Claude, ChatGPT і Cursor
Збірка застосунку через розмову з AI
Вбудовані база даних, акаунти й завдання за розкладом
Листи й сповіщення без окремих сервісів
Публікація у веб, App Store і Google Play
Автоматичні SEO-налаштування
Підключення Stripe, Google-входу, Zapier', 'Connects to Claude, ChatGPT and Cursor
Build an app through a conversation with AI
Built-in database, accounts and scheduled tasks
Emails and notifications without extra tools
Publish to the web, App Store and Google Play
Automatic SEO settings
Stripe, Google sign-in and Zapier connections', 'Люди без досвіду програмування, які вже користуються AI-асистентами й хочуть перетворити ідею на робочий застосунок.', 'People without coding experience who already use AI assistants and want to turn an idea into a working app.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
