INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Floot works as an add-on to the AI assistant you already use. You connect it to Claude, ChatGPT or Cursor, then describe in the chat what app you need, and Floot builds it completely, with a database, hosting and its own link. No git, terminal or separate build credits are needed. The app can store data, let users register, run recurring tasks on a schedule and send emails, receipts and notifications. Publishing takes one click: to the web, and to the App Store and Google Play. SEO settings are added automatically so search engines can find the project, and Floot walks you step by step through connecting Stripe, Google sign-in, Zapier and other services. The free plan lets you try the service; paid plans add more daily actions, AI credits for app features and hosting.', 'manual' FROM DUAL WHERE @new = 1;
