-- Fabricate AI — Веб-розробка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fabricate.build' OR LOWER(`name`) = LOWER('Fabricate AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Fabricate AI', NULL, 'https://fabricate.build', NULL, NULL, 'AI-конструктор застосунків: опишіть ідею кількома реченнями — і за кілька хвилин отримаєте робочий застосунок із входом користувачів і збереженням даних, опублікований за власним посиланням.', 'An AI app builder: describe your idea in a few sentences and within minutes get a working app with user sign-in and saved data, published at its own link.', 'Fabricate AI створює робочі застосунки за звичайним текстовим описом, без жодного коду. Можна написати, що потрібно, своїми словами, додати фото чи ескіз — і через одну-чотири хвилини поруч із чатом з''явиться готовий застосунок, у якому кнопки й форми вже працюють. Прикладами можуть бути сайт для запису в салон, бронювання столиків у ресторані, клієнтський кабінет, облік рахунків, розклад команди чи невеликий інтернет-магазин. Застосунки підтримують вхід користувачів і збереження даних, адаптовані під телефони. Опублікувати результат можна одним кліком за власним посиланням, а змінювати — просто просячи AI в чаті. Для швидкого старту є бібліотека готових шаблонів сайтів: портфоліо, лендінги, сторінки для музикантів, подій, місцевого бізнесу та магазинів. Безкоштовний тариф дозволяє тримати один застосунок онлайн; платні дають більше кредитів, приватні застосунки, власний домен і прибирають значок сервісу.', 'Fabricate AI creates working apps from a plain text description, with no code at all. Write what you need in your own words, add a photo or sketch, and one to four minutes later a finished app appears next to the chat, with buttons and forms that already work. Examples include a booking site for a salon, restaurant reservations, a client portal, invoice tracking, a team schedule or a small online shop. Apps support user sign-in and saved data and work on phones. You can publish the result with one click at its own link and change it simply by asking the AI in the chat. For a quick start there is a library of website templates: portfolios, landing pages, pages for musicians, events, local businesses and stores. The free plan keeps one app online; paid plans add credits, private apps and a custom domain, and remove the service badge.', 'Створення застосунку з текстового опису, фото чи ескізу
Вхід користувачів і збереження даних
Публікація за власним посиланням в один клік
Зміни через чат без коду
Шаблони сайтів для різних ніш
Власний домен і приватні застосунки на платних тарифах', 'App from a text description, photo or sketch
User sign-in and saved data
One-click publishing at your own link
Changes through chat without code
Website templates for different niches
Custom domain and private apps on paid plans', 'Власники малого бізнесу, фрилансери й усі, кому потрібен простий застосунок або сайт без залучення розробників.', 'Small business owners, freelancers and anyone who needs a simple app or website without hiring developers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
