-- Lightfield — CRM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lightfield.app' OR LOWER(`name`) = LOWER('Lightfield'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Lightfield', NULL, 'https://lightfield.app', NULL, NULL, 'CRM з AI, що сама оновлюється з листів, дзвінків і зустрічей із клієнтами: її агенти ведуть розсилки потенційним клієнтам, позначають угоди під загрозою й підказують, на чому зосередитись.', 'An AI CRM that updates itself from emails, calls and meetings with customers: its agents run outreach to prospects, flag deals at risk and suggest where to focus.', 'Lightfield — система обліку клієнтів, яка не потребує ручного заповнення: записи оновлюються автоматично з кожної взаємодії з клієнтом. Сервіс синхронізується з поштою, календарем і Slack, записує й розшифровує зустрічі. На основі зібраних даних вбудовані AI-агенти оцінюють цільові компанії за сигналами на кшталт нового раунду інвестицій, призначення керівника, зростання штату чи зміни технологій, готують персональні листи для холодних розсилок і відповіді після зустрічей, які менеджер лише перевіряє й підтверджує. Система також помічає угоди, що можуть зірватися, і підказує, куди спрямувати зусилля. Підтримуються власні типи об''єктів, налаштування воронки продажів, а на старших тарифах — автоматизації, ланцюжки листів, дашборди, синхронізація з LinkedIn і збагачення даних. Є 14-денний безкоштовний пробний період.', 'Lightfield is a customer management system that does not need manual data entry: records update automatically from every customer interaction. It syncs with email, calendar and Slack and records and transcribes meetings. Based on the collected data, built-in AI agents score target companies by signals such as a new funding round, an executive hire, headcount growth or a technology change, and draft personal emails for cold outreach and meeting follow-ups that a manager only reviews and approves. The system also spots deals that may fall through and suggests where to put effort. Custom object types and pipeline configuration are supported, and higher plans add automations, email sequences, dashboards, LinkedIn sync and data enrichment. There is a 14-day free trial.', 'Автоматичне оновлення записів із листів і зустрічей
Запис і розшифровка зустрічей
Синхронізація з поштою, календарем і Slack
Оцінка компаній за сигналами готовності до покупки
AI-агенти для холодних розсилок і листів після зустрічей
Позначення угод під загрозою
Ланцюжки листів, дашборди й автоматизації', 'Automatic record updates from emails and meetings
Meeting recording and transcription
Email, calendar and Slack sync
Company scoring by buying signals
AI agents for cold outreach and follow-ups
Flags deals at risk
Email sequences, dashboards and automations', 'Засновники стартапів і невеликі команди продажів, які хочуть вести клієнтів без ручного заповнення CRM.', 'Startup founders and small sales teams who want to manage customers without filling in a CRM by hand.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
