INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Lightfield is a customer management system that does not need manual data entry: records update automatically from every customer interaction. It syncs with email, calendar and Slack and records and transcribes meetings. Based on the collected data, built-in AI agents score target companies by signals such as a new funding round, an executive hire, headcount growth or a technology change, and draft personal emails for cold outreach and meeting follow-ups that a manager only reviews and approves. The system also spots deals that may fall through and suggests where to put effort. Custom object types and pipeline configuration are supported, and higher plans add automations, email sequences, dashboards, LinkedIn sync and data enrichment. There is a 14-day free trial.', 'manual' FROM DUAL WHERE @new = 1;
