-- OpenClaw — Автоматизація
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'openclaw.ai' OR LOWER(`name`) = LOWER('OpenClaw'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'OpenClaw', NULL, 'https://openclaw.ai', NULL, NULL, 'Безкоштовний AI-асистент із відкритим кодом, що працює на вашому комп''ютері й виконує справи через WhatsApp, Telegram чи інший месенджер: розбирає пошту, надсилає листи, веде календар, реєструє на рейси.', 'A free open-source AI assistant that runs on your computer and gets things done via WhatsApp, Telegram or another messenger: sorts email, sends messages, manages your calendar and checks you in for flights.', 'OpenClaw — персональний AI-асистент, який не просто відповідає на запитання, а виконує конкретні дії. Ним керують через звичні месенджери, наприклад WhatsApp чи Telegram: можна попросити розібрати вхідну пошту, надіслати лист, внести подію в календар або зареєструватися на рейс. Асистент встановлюється і працює на вашому власному комп''ютері, тож пам''ять, навички, обрані AI-моделі та дані лишаються під вашим контролем. Проєкт має відкритий код, його підтримує незалежна некомерційна організація; підписки, платного хмарного тарифу чи власного токена немає. Користуватися можна самостійно або розгорнути асистента для команди. Встановлення вимагає базових технічних навичок, є кілька варіантів інсталяції та документація.', 'OpenClaw is a personal AI assistant that does not just answer questions but takes concrete actions. You control it through familiar messengers such as WhatsApp or Telegram: ask it to sort your inbox, send an email, add an event to your calendar or check you in for a flight. The assistant is installed and runs on your own computer, so memory, skills, chosen AI models and data stay under your control. The project is open source and maintained by an independent non-profit organization; there is no subscription, paid cloud plan or token. You can use it yourself or deploy it for a team. Installation requires basic technical skills; several install options and documentation are available.', 'Керування через WhatsApp, Telegram та інші месенджери
Розбір пошти й надсилання листів
Ведення календаря
Реєстрація на рейси
Робота на власному комп''ютері, дані під вашим контролем
Вибір власних AI-моделей і навичок
Відкритий код без підписки', 'Control via WhatsApp, Telegram and other messengers
Inbox sorting and sending emails
Calendar management
Flight check-in
Runs on your own computer, data under your control
Choose your own AI models and skills
Open source with no subscription', 'Технічно впевнені користувачі й невеликі команди, які хочуть персонального AI-помічника без передачі даних стороннім сервісам.', 'Technically confident users and small teams who want a personal AI helper without handing data to third-party services.', 'desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
