-- buzzabout — SMM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'buzzabout.ai' OR LOWER(`name`) = LOWER('buzzabout'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'buzzabout', NULL, 'https://buzzabout.ai', NULL, NULL, 'Платформа соціального аналізу для маркетологів і агенцій: досліджує обговорення в Reddit, TikTok, YouTube, Instagram, X і LinkedIn та знаходить болі, заперечення, запити й теми аудиторії.', 'A social intelligence platform for marketers and agencies: it studies conversations on Reddit, TikTok, YouTube, Instagram, X and LinkedIn and finds your audience''s pains, objections, requests and topics.', 'buzzabout допомагає зрозуміти, що люди насправді говорять про бренд, конкурентів чи цілу категорію товарів. Сервіс збирає дописи й коментарі з Reddit, TikTok, YouTube, Instagram, X і LinkedIn та автоматично виявляє в них закономірності: болі й заперечення клієнтів, запити на функції, тон спілкування, типи гачків у контенті, емоції, наративи та візуальні стилі. Готові категорії задавати не потрібно — платформа знаходить їх сама. Ставити запитання можна звичайною мовою, а кожна відповідь спирається на реальні згадки й посилається на дописи, з яких зроблено висновок. Результати оформлюються у звіти й графіки, цікаві фрагменти можна зберігати. На тарифах доступні агенти постійного моніторингу, дослідження з кількох джерел, експорт у CSV і PDF, вебхуки, API та підключення через MCP. Є безкоштовний пробний період.', 'buzzabout helps you understand what people really say about a brand, competitors or a whole product category. The service collects posts and comments from Reddit, TikTok, YouTube, Instagram, X and LinkedIn and automatically finds patterns in them: customer pains and objections, feature requests, tone of voice, hook types in content, emotions, narratives and visual styles. You do not need to define categories in advance; the platform finds them itself. You can ask questions in plain language, and every answer is based on real mentions and links to the posts it came from. Results are turned into reports and charts, and useful snippets can be saved. Plans include ongoing listening agents, multi-source research, CSV and PDF export, webhooks, an API and MCP connections. There is a free trial.', 'Аналіз обговорень у шести соцмережах
Автоматичне виявлення болей, заперечень і запитів
Запитання звичайною мовою з посиланнями на джерела
Звіти й графіки за результатами
Агенти постійного моніторингу згадок
Експорт у CSV/PDF, API і MCP-підключення', 'Analysis of conversations across six social networks
Automatic detection of pains, objections and requests
Plain-language questions with source links
Reports and charts from results
Ongoing mention listening agents
CSV/PDF export, API and MCP connections', 'Маркетологи, продакт-менеджери та агенції, яким потрібні дані з соцмереж для кампаній і продуктових рішень.', 'Marketers, product managers and agencies that need social media data for campaigns and product decisions.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
