SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'articos.com' OR LOWER(`name`) = LOWER('Articos'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Articos', NULL, 'https://articos.com', NULL, NULL, 'Платформа досліджень користувачів на основі AI: проводить інтерв''ю з синтетичними персонами вашої цільової аудиторії й приблизно за 30 хвилин видає структурований звіт замість тижнів традиційного дослідження.', 'An AI user research platform: it interviews synthetic personas of your target audience and delivers a structured report in about 30 minutes instead of weeks of traditional research.', 'Articos допомагає продуктовим командам, консультантам і агенціям перевіряти ідеї та рішення на цільовій аудиторії без рекрутингу респондентів і довгого очікування. Ви формулюєте мету дослідження, а сервіс проводить інтерв''ю з синтетичними персонами — змодельованими представниками вашої аудиторії. Кожну персону опитують окремо, не підказуючи їй гіпотезу, щоб відповіді не підлаштовувались під очікування. На виході — структурований звіт, яким можна поділитися з командою. Сервіс підходить, щоб визначити ідеального клієнта, з''ясувати, які завдання люди хочуть розв''язати й що їх зупиняє перед покупкою, порівняти варіанти через A/B-тести та відшліфувати сценарій інтерв''ю. За результатами можна ставити додаткові уточнювальні запитання. На старших тарифах доступні дзвінки з реальними представниками аудиторії, необмежена кількість досліджень і звіти під власним брендом. Є 7-денний безкоштовний пробний період без картки, а також разові пакети досліджень.', 'Articos helps product teams, consultants and agencies test ideas and decisions with their target audience without recruiting respondents or waiting for weeks. You set the research goal and the service interviews synthetic personas, modeled representatives of your audience. Each persona is interviewed separately without being told the hypothesis, so answers do not bend to expectations. The output is a structured report you can share with your team. The service helps define your ideal customer, find out what jobs people want done and what stops them before buying, compare options with A/B tests and refine an interview script. You can ask follow-up questions about the results. Higher plans add calls with real audience members, unlimited research and white-label reports. There is a 7-day free trial with no card, as well as one-time research packs.', 'Інтерв''ю з синтетичними персонами цільової аудиторії
Звіт за дослідженням приблизно за 30 хвилин
A/B-тестування варіантів
Допомога з написанням сценарію інтерв''ю
Уточнювальні запитання до результатів
Живі дзвінки з аудиторією на платних тарифах
Звіти під власним брендом (тариф Pro)', 'Interviews with synthetic personas of your audience
Research report in about 30 minutes
A/B testing of options
Help writing the interview script
Follow-up questions on results
Live calls with your audience on paid plans
White-label reports (Pro plan)', 'Продуктові команди, SaaS-компанії, консультанти й агенції, яким потрібні дослідження користувачів швидко й недорого.', 'Product teams, SaaS companies, consultants and agencies that need fast, affordable user research.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
