-- Jobbyo — Автоматизація
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'jobbyo.ai' OR LOWER(`name`) = LOWER('Jobbyo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Jobbyo', NULL, 'https://jobbyo.ai', NULL, NULL, 'AI-агент для пошуку роботи: щоранку підбирає вакансії під ваші побажання щодо зарплати й віддаленої роботи, адаптує резюме, пише супровідні листи й подає заявки, які ви підтверджуєте одним дотиком.', 'An AI job search agent: every morning it picks roles that match your salary and remote preferences, tailors your resume, writes cover letters and submits applications you approve with one tap.', 'Jobbyo бере на себе рутину пошуку роботи. Сервіс щодня шукає вакансії на загальних і нішевих майданчиках та формує добірку ролей, що відповідають вашим очікуванням щодо зарплати й формату роботи. Для кожної вакансії він підлаштовує резюме під опис посади, готує супровідний лист, відповідає на відбіркові запитання й оформлює заявку так, щоб її коректно прочитали автоматичні системи відбору кандидатів. Перш ніж заявку буде надіслано, ви можете переглянути її й підтвердити чи відхилити, а агент враховує ваші оцінки й поступово краще розуміє, що вам підходить. Щотижня надходить звіт про прогрес. Залежно від тарифу Jobbyo лише знаходить вакансії й готує документи або ще й сам подає до десяти заявок на день; на найвищому тарифі кожну заявку додатково перевіряє людина. Оплата щотижнева або щоквартальна, є безкоштовний пробний період.', 'Jobbyo takes over the routine of looking for a job. Every day it searches general and niche job boards and puts together a list of roles that match your salary and work format expectations. For each role it tailors your resume to the job description, prepares a cover letter, answers screening questions and formats the application so automated applicant tracking systems read it correctly. Before an application is sent you can review it and approve or reject it, and the agent learns from your ratings to understand better what suits you. A weekly progress report arrives. Depending on the plan, Jobbyo only finds roles and prepares documents or also submits up to ten applications a day itself; on the top plan a person additionally checks every application. Billing is weekly or quarterly, and there is a free trial.', 'Щоденний підбір вакансій під зарплату й формат роботи
Адаптація резюме під кожну вакансію
Супровідні листи й відповіді на відбіркові запитання
Автоматична подача до 10 заявок на день
Перегляд і підтвердження кожної заявки
Навчання на ваших оцінках
Щотижневий звіт про прогрес', 'Daily role matching by salary and work format
Resume tailored to each role
Cover letters and screening question answers
Automatic submission of up to 10 applications a day
Review and approval of every application
Learns from your ratings
Weekly progress report', 'Люди, які шукають роботу (зокрема віддалену) і хочуть заощадити час на пошуку вакансій і оформленні заявок.', 'Job seekers, including those looking for remote work, who want to save time on searching and applying.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
