-- Wakeman — CRM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wakeman.ai' OR LOWER(`name`) = LOWER('Wakeman'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Wakeman', NULL, 'https://wakeman.ai', NULL, NULL, 'AI-адміністратор і телефонна служба для сантехніків, фахівців з опалення й кондиціонування та електриків: відповідає на пропущені дзвінки від імені вашої компанії, відрізняє аварію від планової заявки й надсилає вам заявку повідомленням.', 'An AI receptionist and answering service for plumbers, HVAC technicians and electricians: it answers missed calls in your company''s name, tells an emergency from a routine job and texts you the job.', 'Wakeman створено для невеликих сервісних компаній — сантехніків, фахівців з опалення та кондиціонування, електриків, покрівельників і бригад з відновлення після пошкоджень. Коли ви на об''єкті й не можете взяти слухавку, Wakeman відповідає на дзвінок від імені вашої компанії в будь-який час доби, з''ясовує, що сталося, записує адресу й контакти, відрізняє термінову аварію від звичайного запиту й одразу надсилає вам заявку текстовим повідомленням. За бажанням можна увімкнути запис клієнтів на виконання робіт. Налаштування займає близько десяти хвилин: сервіс знаходить вашу компанію в Google, читає сайт, дає послухати приклад дзвінка й змінити формулювання, після чого достатньо переадресувати пропущені дзвінки коротким кодом. Номер телефону лишається вашим. Тарифи відрізняються тим, коли відповідає Wakeman — лише в неробочий час чи на будь-який пропущений дзвінок — і кількістю хвилин на місяць. Сервіс орієнтований на ринок США.', 'Wakeman is built for small trade businesses: plumbers, heating and cooling technicians, electricians, roofers and restoration crews. When you are on a job and cannot pick up, Wakeman answers in your company''s name at any hour, finds out what happened, writes down the address and contact details, tells an urgent emergency from a regular request and immediately texts you the job. Booking customers for work can be switched on if you want. Setup takes about ten minutes: the service finds your business on Google, reads your website, lets you hear a sample call and adjust the wording, after which you forward missed calls with a short code. You keep your phone number. Plans differ in when Wakeman answers, only after hours or for any missed call, and in the number of minutes per month. The service is focused on the US market.', 'Відповідь на пропущені дзвінки від імені компанії 24/7
Розрізнення аварійних і планових заявок
Заявка з адресою й контактами у текстовому повідомленні
Запис клієнтів на роботи (за бажанням)
Налаштування за даними з Google і сайту компанії
Збереження власного номера телефону', 'Answers missed calls in your company''s name 24/7
Tells emergencies from routine jobs
Job with address and contacts by text message
Customer booking (optional)
Setup from your Google listing and website
Keep your own phone number', 'Невеликі сервісні компанії у США: сантехніки, фахівці з опалення й кондиціонування, електрики, покрівельники.', 'Small trade businesses in the US: plumbers, HVAC technicians, electricians, roofers.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
