INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Wakeman is built for small trade businesses: plumbers, heating and cooling technicians, electricians, roofers and restoration crews. When you are on a job and cannot pick up, Wakeman answers in your company''s name at any hour, finds out what happened, writes down the address and contact details, tells an urgent emergency from a regular request and immediately texts you the job. Booking customers for work can be switched on if you want. Setup takes about ten minutes: the service finds your business on Google, reads your website, lets you hear a sample call and adjust the wording, after which you forward missed calls with a short code. You keep your phone number. Plans differ in when Wakeman answers, only after hours or for any missed call, and in the number of minutes per month. The service is focused on the US market.', 'manual' FROM DUAL WHERE @new = 1;
