-- Notis — Автоматизація
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'notis.ai' OR LOWER(`name`) = LOWER('Notis'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Notis', NULL, 'https://notis.ai', NULL, NULL, 'AI-асистент, якому дають доручення в WhatsApp, iMessage, Telegram, Slack чи поштою: голосовим повідомленням, фото чи пересланим листом. Він виконує завдання в понад тисячі сервісів, зокрема Gmail, календарі й Notion.', 'An AI assistant you give tasks to in WhatsApp, iMessage, Telegram, Slack or by email, as a voice note, photo or forwarded email. It gets the work done across 1,000+ services including Gmail, calendars and Notion.', 'Notis працює як особистий помічник, якому достатньо написати чи надіслати голосове повідомлення в месенджер. Можна попросити нагадати клієнту про неоплачений рахунок, перетворити голосові ідеї на нотатку, переслати лист і доручити з ним розібратися або поділитися фото — Notis виконає завдання в сервісах, якими ви вже користуєтесь. Підтримуються Gmail, календарі, Notion, Dropbox та понад тисяча інших застосунків, тож не доводиться перемикатися між вкладками й копіювати дані. Асистент також стежить за тим, що легко забути, наприклад повторно нагадує, якщо відповіді немає. Окрім месенджерів, є веб- і настільний застосунок. Особливість сервісу — можна підключити вже оплачену підписку ChatGPT чи Claude, щоб витрати на AI-модель ішли з неї, а не з ліміту Notis; ключі API для цього не потрібні. Оплата залежить від кількості виконаних завдань, є безкоштовний старт.', 'Notis works like a personal assistant you simply message or send a voice note to. Ask it to remind a client about an unpaid invoice, turn spoken ideas into a note, forward an email and have it handled, or share a photo, and Notis completes the task in the services you already use. Gmail, calendars, Notion, Dropbox and more than a thousand other apps are supported, so you do not have to switch tabs or copy data. The assistant also keeps track of things that are easy to forget, for example following up again if there is no reply. Besides messengers, there is a web and desktop app. A distinctive feature: you can connect an existing ChatGPT or Claude subscription so AI model costs come from it rather than your Notis allowance; no API keys are needed. Pricing depends on the number of tasks completed, and there is a free start.', 'Доручення через WhatsApp, iMessage, Telegram, Slack і пошту
Голосові повідомлення, фото й переслані листи як завдання
Дії в Gmail, календарі, Notion, Dropbox та 1000+ сервісах
Повторні нагадування, якщо немає відповіді
Веб- і настільний застосунок
Підключення власної підписки ChatGPT або Claude', 'Tasks via WhatsApp, iMessage, Telegram, Slack and email
Voice notes, photos and forwarded emails as tasks
Actions in Gmail, calendar, Notion, Dropbox and 1,000+ services
Automatic follow-ups when there is no reply
Web and desktop app
Connect your own ChatGPT or Claude subscription', 'Засновники, підприємці й зайняті професіонали, які хочуть делегувати рутинні справи з телефона.', 'Founders, entrepreneurs and busy professionals who want to delegate routine tasks from their phone.', 'web,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
