INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Notis works like a personal assistant you simply message or send a voice note to. Ask it to remind a client about an unpaid invoice, turn spoken ideas into a note, forward an email and have it handled, or share a photo, and Notis completes the task in the services you already use. Gmail, calendars, Notion, Dropbox and more than a thousand other apps are supported, so you do not have to switch tabs or copy data. The assistant also keeps track of things that are easy to forget, for example following up again if there is no reply. Besides messengers, there is a web and desktop app. A distinctive feature: you can connect an existing ChatGPT or Claude subscription so AI model costs come from it rather than your Notis allowance; no API keys are needed. Pricing depends on the number of tasks completed, and there is a free start.', 'manual' FROM DUAL WHERE @new = 1;
