-- remio — Нотатки
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'remio.ai' OR LOWER(`name`) = LOWER('remio'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'remio', NULL, 'https://remio.ai', NULL, NULL, 'AI-агент для роботи зі знаннями: збирає вебсторінки, зустрічі, листи й файли в особисту базу та на їх основі відповідає на запитання й готує документи, презентації PowerPoint і таблиці Excel.', 'An AI agent for knowledge work: it gathers web pages, meetings, emails and files into a personal knowledge base and uses them to answer questions and prepare documents, PowerPoint decks and Excel spreadsheets.', 'remio — настільний застосунок для Windows і Mac, який перетворює ваші файли, зустрічі, листи й дослідження на робочі матеріали. Він зберігає вебсторінки, розбирає локальні документи понад 30 форматів — тексти, PDF, таблиці, презентації, зображення, аудіо й відео — і робить усе це доступним для пошуку та запитань до AI, які враховують ваш контекст. На основі зібраного remio може підготувати презентацію, що повністю редагується в PowerPoint із вашими шаблонами й стилем, оновити наявну презентацію, попрацювати з Excel чи провести глибоке дослідження. Підтримуються понад 30 AI-моделей, підключення Google Drive, Gmail, Microsoft 365, Slack, GitHub та інших сервісів, готові навички для досліджень, письма й аналізу. Основні дані зберігаються локально. На платних тарифах є AI-асистент зустрічей, голосовий диктант, генерація зображень і можливість підключити власні ключі. Мобільний застосунок працює лише разом із настільним.', 'remio is a desktop app for Windows and Mac that turns your files, meetings, emails and research into work deliverables. It saves web pages, parses local documents in more than 30 formats, including text, PDF, spreadsheets, presentations, images, audio and video, and makes all of it searchable and available for AI questions that take your context into account. From the collected material remio can prepare a presentation that is fully editable in PowerPoint using your templates and style, update an existing deck, work with Excel or run deep research. More than 30 AI models are supported, along with connections to Google Drive, Gmail, Microsoft 365, Slack, GitHub and other services, and ready-made skills for research, writing and analysis. Core data is stored locally. Paid plans add an AI meeting assistant, voice dictation, image generation and the option to bring your own keys. The mobile app works only together with the desktop app.', 'Збереження вебсторінок і розбір файлів понад 30 форматів
Пошук і запитання до AI по власній базі знань
Створення редагованих презентацій PowerPoint
Робота з Excel і глибокі дослідження
Понад 30 AI-моделей на вибір
Підключення Google Drive, Gmail, Microsoft 365, Slack, GitHub
AI-асистент зустрічей і голосовий диктант
Локальне зберігання основних даних', 'Saves web pages and parses files in 30+ formats
Search and AI questions over your own knowledge base
Editable PowerPoint presentations
Excel work and deep research
30+ AI models to choose from
Google Drive, Gmail, Microsoft 365, Slack and GitHub connections
AI meeting assistant and voice dictation
Local storage of core data', 'Фахівці, дослідники й консультанти, які працюють з великою кількістю документів, листів і зустрічей.', 'Professionals, researchers and consultants who work with many documents, emails and meetings.', 'desktop,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
