SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'automateed.com' OR LOWER(`name`) = LOWER('Automateed'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Automateed', NULL, 'https://automateed.com', NULL, NULL, 'AI-платформа для створення й продажу книжок: з теми й плану генерує редагований чернетковий текст, допомагає з обкладинками й ілюстраціями, експортує в PDF та EPUB і дає змогу опублікувати та продавати книжку.', 'An AI platform for creating and selling books: it generates an editable draft from a topic and outline, helps with covers and illustrations, exports to PDF and EPUB and lets you publish and sell the book.', 'Automateed об''єднує в одному робочому просторі всі етапи створення книжки. Ви обираєте тему й визначаєте розділи, а сервіс готує чернетку кількох розділів, яку можна вільно редагувати: додавати власні приклади, перевіряти факти й джерела, змінювати формулювання та структуру. Далі можна оформити дизайн, створити обкладинку й ілюстрації та експортувати рукопис у PDF чи EPUB. Окремий сценарій допомагає зробити ілюстровану дитячу книжку з контролем узгодженості зображень і відповідності віку. Готову книжку можна опублікувати й продавати безпосередньо через платформу, а також створювати друковані видання, аудіокниги, курси й сайти авторів. Почати можна з безкоштовного попереднього перегляду без картки.', 'Automateed brings every stage of making a book into one workspace. You choose a topic and define chapters, and the service prepares a multi-chapter draft you can edit freely: add your own examples, check facts and sources, and change the wording and structure. Then you can shape the design, create a cover and illustrations and export the manuscript to PDF or EPUB. A separate workflow helps make an illustrated children''s book while checking image consistency and age suitability. A finished book can be published and sold directly through the platform, and you can also create print editions, audiobooks, courses and author websites. You can start with a free preview and no card.', 'Чернетка книжки з теми й плану розділів
Повне редагування тексту й структури
Обкладинки та ілюстрації
Експорт у PDF та EPUB
Сценарій створення ілюстрованих дитячих книжок
Публікація й продаж книжки на платформі
Друковані видання, аудіокниги й сайти авторів', 'Book draft from a topic and chapter outline
Full editing of text and structure
Covers and illustrations
Export to PDF and EPUB
Workflow for illustrated children''s books
Publishing and selling on the platform
Print editions, audiobooks and author websites', 'Автори, експерти й підприємці, які хочуть створити й продавати електронну чи друковану книжку.', 'Authors, experts and entrepreneurs who want to create and sell an ebook or print book.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
