-- Anijam — 3D та анімація
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'anijam.ai' OR LOWER(`name`) = LOWER('Anijam'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Anijam', NULL, 'https://anijam.ai', NULL, NULL, 'AI-агент для створення анімованих відео в чаті: перетворює текст, сценарій, зображення чи аудіо на анімацію в різних стилях, із синхронізацією губ і озвученням понад 30 мовами.', 'An AI agent for making animated videos in a chat: it turns text, a script, an image or audio into animation in different styles, with lip sync and voiceover in 30+ languages.', 'Anijam дозволяє створювати анімацію, просто описуючи бажаний результат у чаті. Почати можна з короткого текстового запиту, повного сценарію, який сервіс розбиває на сцени, зображення, яке потрібно оживити, або голосу чи музики. Можна створити власного анімованого персонажа й обрати візуальний стиль: м''яку мальовану анімацію, блоковий світ у стилі відеоігор, кінематографічне 3D чи класичний двовимірний мультфільм. Серед додаткових інструментів — синхронізація рухів губ з будь-яким аудіо, генератор озвучення понад 30 мовами та редактор сцен для точного налаштування кадрів. Сервіс підходить для інтро й пояснювальних роликів на YouTube, реклами, коротких відео для соцмереж, навчальних матеріалів, бізнес-презентацій і святкових привітань. Є мобільний застосунок. Тарифи працюють на кредитах і відрізняються доступними моделями, кількістю одночасних завдань і якістю експорту.', 'Anijam lets you create animation by simply describing what you want in a chat. You can start with a short text prompt, a full script that the service splits into scenes, an image to bring to life, or a voice or music track. You can create your own animated character and pick a visual style: soft hand-painted animation, a block-style game world, cinematic 3D or a classic 2D cartoon. Extra tools include lip sync to any audio, a voiceover generator in more than 30 languages and a scene editor for fine-tuning frames. It suits YouTube intros and explainers, ads, short social videos, lessons, business presentations and holiday greetings. There is a mobile app. Plans run on credits and differ in available models, concurrent tasks and export quality.', 'Анімація з тексту, сценарію, зображення чи аудіо
Створення власних анімованих персонажів
Різні стилі: мальований, 3D, класичний 2D
Синхронізація губ з аудіо
Озвучення понад 30 мовами
Редактор сцен для налаштування кадрів
Мобільний застосунок', 'Animation from text, a script, an image or audio
Create your own animated characters
Styles: hand-painted, 3D, classic 2D
Lip sync to audio
Voiceover in 30+ languages
Scene editor for frame tuning
Mobile app', 'Автори контенту для YouTube і соцмереж, маркетологи, викладачі й малий бізнес, яким потрібні анімовані відео без навичок анімації.', 'YouTube and social media creators, marketers, teachers and small businesses who need animated videos without animation skills.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
