-- Jupid — Фінанси
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'jupid.com' OR LOWER(`name`) = LOWER('Jupid'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Jupid', NULL, 'https://jupid.com', NULL, NULL, 'AI-бухгалтер для фрилансерів і власників LLC у США: підключається до банку, автоматично розносить витрати за категоріями, знаходить податкові відрахування й формує Schedule C. Перші 100 транзакцій безкоштовно.', 'An AI accountant for freelancers and LLC owners in the US: connects to your bank, categorizes expenses automatically, finds tax deductions and generates your Schedule C. First 100 transactions free.', 'Jupid автоматизує облік і податки для самозайнятих та невеликих компаній у США. Після підключення банківських рахунків, Stripe, Deel та інших сервісів він сам розподіляє транзакції за категоріями витрат і доходів, запам''ятовує ваших постачальників і з часом працює точніше. Сервіс шукає витрати, які можна врахувати як податкові відрахування, і формує декларацію Schedule C, яку потрібно подати до податкової служби США. На платному тарифі доступні фінансові звіти, подання федеральних і штатних декларацій з перевіркою сертифікованим бухгалтером, квартальні податкові розрахунки, нагадування про строки й допомога з реєстрацією LLC. Ставити запитання про свої фінанси можна в WhatsApp чи iMessage, а розробники можуть підключити Jupid до AI-агентів через MCP-сервер, зокрема в Claude Code чи Cursor. На сайті також є понад 80 безкоштовних калькуляторів і довідників.', 'Jupid automates bookkeeping and taxes for self-employed people and small companies in the US. After you connect bank accounts, Stripe, Deel and other services, it sorts transactions into expense and income categories itself, remembers your vendors and gets more accurate over time. The service looks for expenses that qualify as tax deductions and generates the Schedule C form filed with the IRS. The paid plan adds financial reports, federal and state tax filing reviewed by a certified accountant, quarterly tax estimates, due date alerts and help forming an LLC. You can ask questions about your finances in WhatsApp or iMessage, and developers can connect Jupid to AI agents through an MCP server, including in Claude Code or Cursor. The site also has more than 80 free calculators and guides.', 'Автоматична категоризація банківських транзакцій
Пошук податкових відрахувань
Формування Schedule C
Подання декларацій з перевіркою бухгалтером
Квартальні податкові розрахунки й нагадування
Запитання про фінанси в WhatsApp та iMessage
MCP-сервер для AI-агентів', 'Automatic categorization of bank transactions
Tax deduction finder
Schedule C generation
Tax filing reviewed by an accountant
Quarterly tax estimates and alerts
Finance questions in WhatsApp and iMessage
MCP server for AI agents', 'Фрилансери, підрядники, власники LLC і засновники стартапів у США.', 'Freelancers, contractors, LLC owners and startup founders in the US.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
