INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Jupid automates bookkeeping and taxes for self-employed people and small companies in the US. After you connect bank accounts, Stripe, Deel and other services, it sorts transactions into expense and income categories itself, remembers your vendors and gets more accurate over time. The service looks for expenses that qualify as tax deductions and generates the Schedule C form filed with the IRS. The paid plan adds financial reports, federal and state tax filing reviewed by a certified accountant, quarterly tax estimates, due date alerts and help forming an LLC. You can ask questions about your finances in WhatsApp or iMessage, and developers can connect Jupid to AI agents through an MCP server, including in Claude Code or Cursor. The site also has more than 80 free calculators and guides.', 'manual' FROM DUAL WHERE @new = 1;
