SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'x-pilot.ai' OR LOWER(`name`) = LOWER('X-Pilot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'X-Pilot', NULL, 'https://x-pilot.ai', NULL, NULL, 'AI-сервіс для створення навчальних відео й курсів: перетворює тему, PDF, презентацію, документ чи сторінку сайту на редаговане відео з візуалізацією знань і, за бажанням, AI-аватаром викладача.', 'An AI service for creating course and training videos: it turns a topic, PDF, presentation, document or web page into an editable video with knowledge visualization and an optional AI teacher avatar.', 'X-Pilot призначений для тих, хто створює навчальні матеріали: викладачів, авторів курсів, корпоративних тренерів і маркетингових команд. Достатньо задати тему або завантажити вихідні матеріали — PDF, презентацію PowerPoint, текстовий документ, посилання на сторінку чи сценарій, — і сервіс створить навчальне відео або цілу серію за розділами. Відео лишаються повністю редагованими: зміни можна вносити звичайною мовою. Акцент зроблено на точності: сервіс підтримує відстеження джерел, щоб можна було перевірити, звідки взято кожне твердження, і дозволяє створювати довгі відео тривалістю понад 20 хвилин. Складні поняття пояснюються через візуалізацію знань, а за бажанням можна додати AI-аватара викладача. Серед сценаріїв — створення курсів, навчання з дотримання правил, корпоративні тренінги, технічні інструкції, підготовка до сертифікацій та іспитів. Інтерфейс доступний кількома мовами, почати можна безкоштовно.', 'X-Pilot is designed for people who create learning materials: teachers, course creators, corporate trainers and marketing teams. Set a topic or upload source material, such as a PDF, a PowerPoint presentation, a document, a page link or a script, and the service creates a course video or a whole chapter-based series. Videos stay fully editable, and changes can be made in plain language. The focus is on accuracy: the service supports source tracing so you can check where each statement comes from, and it can create long videos of more than 20 minutes. Complex concepts are explained through knowledge visualization, and an AI teacher avatar can be added if you wish. Use cases include course creation, compliance training, corporate training, technical tutorials, certification and exam prep. The interface is available in several languages, and you can start for free.', 'Відео з теми, PDF, презентації, документа чи URL
Серії відео за розділами курсу
Редагування відео звичайною мовою
Відстеження джерел для перевірки фактів
Довгі відео понад 20 хвилин
Візуалізація складних понять
Необов''язковий AI-аватар викладача', 'Video from a topic, PDF, presentation, document or URL
Chapter-based course video series
Editing videos in plain language
Source tracing for fact checking
Long videos of 20+ minutes
Visualization of complex concepts
Optional AI teacher avatar', 'Викладачі, автори онлайн-курсів, корпоративні тренери й команди навчання персоналу.', 'Teachers, online course creators, corporate trainers and staff training teams.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
