-- Thea — Тести
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'theastudy.com' OR LOWER(`name`) = LOWER('Thea'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Thea', NULL, 'https://theastudy.com', NULL, NULL, 'AI-інструмент для навчання: з конспектів, слайдів, PDF, відео чи посилань на YouTube створює тренувальні запитання й навчальні посібники та допомагає активно повторювати матеріал перед іспитом.', 'An AI study tool: from notes, slides, PDFs, videos or YouTube links it creates practice questions and study guides and helps you actively review material before an exam.', 'Thea допомагає студентам і школярам готуватися до занять та іспитів. Достатньо завантажити навчальні матеріали — слайди лекцій, PDF, документи, презентації, зображення, аудіо, відео, власні нотатки чи посилання на YouTube; загалом підтримується понад 90 типів файлів. З них сервіс одразу створює набір інструментів для навчання: тренувальні запитання, навчальні посібники тощо. Головний режим Smart Study не дає готових відповідей, а ставить запитання за вашим матеріалом, щоб ви самі обмірковували тему й краще її запам''ятовували. Спробувати можна без реєстрації на готових наборах з біології, математики, історії та інших предметів, а створені власні набори завжди безкоштовні. Сервіс доступний понад 80 мовами, у браузері та в мобільному застосунку; окремі рішення є для викладачів і навчальних закладів, а також розширена версія Thea+.', 'Thea helps students prepare for classes and exams. Upload your learning materials, such as lecture slides, PDFs, documents, presentations, images, audio, video, your own notes or YouTube links; more than 90 file types are supported. The service instantly turns them into a set of study tools, including practice questions and study guides. The main Smart Study mode does not hand you ready answers but asks questions based on your material, so you think the topic through yourself and remember it better. You can try it without an account on ready-made kits for biology, math, history and other subjects, and study kits you create are always free. The service is available in more than 80 languages, in the browser and in a mobile app; there are separate offerings for educators and institutions and an extended Thea+ version.', 'Навчальні набори з понад 90 типів файлів і YouTube
Тренувальні запитання й навчальні посібники
Режим активного повторення Smart Study
Спроба без реєстрації на готових наборах
Понад 80 мов
Мобільний застосунок
Рішення для викладачів і навчальних закладів', 'Study kits from 90+ file types and YouTube
Practice questions and study guides
Smart Study active recall mode
Try without an account on ready-made kits
80+ languages
Mobile app
Offerings for educators and institutions', 'Студенти й школярі, які готуються до занять та іспитів, а також викладачі.', 'Students preparing for classes and exams, as well as teachers.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
