SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'thumbnailcreator.com' OR LOWER(`name`) = LOWER('ThumbnailCreator'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ThumbnailCreator', NULL, 'https://thumbnailcreator.com', NULL, NULL, 'AI-генератор обкладинок для YouTube: вставте посилання на відео — і за пів хвилини отримаєте варіанти превʼю, створені з вашого відео, з вашим обличчям і стилем, без навичок дизайну.', 'An AI YouTube thumbnail generator: paste a video link and in under half a minute get thumbnail options built from your video, with your face and style, no design skills needed.', 'ThumbnailCreator допомагає авторам YouTube-каналів швидко робити обкладинки до відео. Достатньо вставити посилання на ролик, і сервіс створить кілька варіантів превʼю на основі самого відео, використовуючи ваше обличчя та впізнаваний стиль каналу. Можна генерувати варіації наявної обкладинки, витягувати обкладинки з YouTube-відео й автоматично оптимізувати зображення. На старших тарифах доступне розширене навчання на вашому обличчі, заміна людини в кадрі й зміна виразу обличчя, необмежене витягування обкладинок і доступ до трендових прикладів. Один кредит дорівнює одній обкладинці. Є 7-денний безкоштовний пробний період з 10 обкладинками; при річній оплаті вся квота на рік стає доступною одразу.', 'ThumbnailCreator helps YouTube creators make video thumbnails quickly. Paste a link to a video and the service creates several thumbnail options based on the video itself, using your face and your channel''s recognizable style. You can generate variations of an existing thumbnail, extract thumbnails from YouTube videos and optimize images automatically. Higher plans add advanced face training, person swap and expression changes, unlimited thumbnail extraction and access to trending examples. One credit equals one thumbnail. There is a 7-day free trial with 10 thumbnails; with annual billing the whole year''s quota is available right away.', 'Обкладинки з посилання на YouTube-відео
Використання вашого обличчя та стилю каналу
Генерація варіацій обкладинки
Витягування обкладинок з YouTube
Автоматична оптимізація зображень
Заміна людини й зміна виразу обличчя (старші тарифи)', 'Thumbnails from a YouTube video link
Uses your face and channel style
Thumbnail variations
YouTube thumbnail extraction
Automatic image optimization
Person swap and expression changes (higher plans)', 'Автори YouTube-каналів, які хочуть швидко робити обкладинки без дизайнера.', 'YouTube creators who want to make thumbnails quickly without a designer.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
