SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trayo.ai' OR LOWER(`name`) = LOWER('Trayo AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Trayo AI', NULL, 'https://trayo.ai', NULL, NULL, 'Сервіс сигналів готовності до покупки для команд продажів: у реальному часі стежить за цільовими компаніями, знаходить потрібну людину в комітеті закупівель і готує персональний лист.', 'A buying-signal service for sales teams: it monitors target companies in real time, finds the right person on the buying committee and drafts a personal email.', 'Trayo AI допомагає продажникам звертатися до компаній саме тоді, коли ті готові купувати. Сервіс у реальному часі відстежує вибрані компанії й помічає сигнали: нові призначення керівників, інвестиції, розширення команд, вакансії чи публікації співробітників про проблеми, які може вирішити ваш продукт. Коли сигнал з''являється, Trayo автоматично визначає людей, які ухвалюють рішення про покупку, і готує чернетку персонального листа. Підключення до CRM, міграція даних чи перевірка безпеки не потрібні — сервіс працює поруч із вашими інструментами. Також доступні пошук компаній і контактів, контактні дані, сповіщення поштою та підключення через MCP. На сайті є безкоштовні інструменти: генератор сигналів, тест доставлюваності листів і калькулятор окупності. Є 7-денний пробний період без картки.', 'Trayo AI helps salespeople reach out to companies exactly when they are ready to buy. The service tracks selected companies in real time and catches signals: new executive hires, funding, team growth, job openings or employee posts about problems your product can solve. When a signal fires, Trayo automatically identifies the people who make the buying decision and drafts a personal email. No CRM access, data migration or security review is required; the service works alongside your existing tools. Company and contact search, contact data, email notifications and MCP access are also available. The site offers free tools: a signal generator, an email deliverability test and an ROI calculator. There is a 7-day trial with no card.', 'Моніторинг цільових компаній у реальному часі
Сигнали: призначення, інвестиції, розширення команд
Автоматичне визначення осіб, що ухвалюють рішення
Чернетки персональних листів
Пошук компаній і контактних даних
Робота без доступу до CRM
Підключення через MCP', 'Real-time monitoring of target companies
Signals: hires, funding, team growth
Automatic identification of decision makers
Personal email drafts
Company and contact data search
Works without CRM access
MCP access', 'Менеджери з продажу та команди виходу на ринок у B2B-компаніях.', 'Sales reps and go-to-market teams at B2B companies.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
