-- GenFlik — Генерація відео
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'genflik.com' OR LOWER(`name`) = LOWER('GenFlik'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'GenFlik', NULL, 'https://genflik.com', NULL, NULL, 'AI-генератор рекламних відео у стилі UGC: з опису товару, посилання чи фото створює готовий ролик з реалістичним аватаром-ведучим, озвученням 31 мовою, субтитрами й музикою — без зйомок.', 'An AI generator of UGC-style video ads: from a product description, link or photos it creates a finished ad with a realistic talking avatar, voiceover in 31 languages, captions and music, with no filming.', 'GenFlik створює рекламні відео у форматі контенту від користувачів для TikTok, Instagram Reels, YouTube Shorts і платної реклами в соцмережах. Почати можна з посилання на товар, текстового опису або кількох фото. Сервіс сам пише сценарій реклами, генерує реалістичного аватара, який розповідає про товар, озвучує текст однією з 31 мови, додає субтитри, фонову музику, кадри з вашими фото товару й фірмову кінцівку. Сценарій можна переглянути й відредагувати безкоштовно, а кредити витрачаються лише на рендер готового MP4. Є режим відео лише з товаром у кадрі та закадровим голосом, клонування голосу, а довжина сценарію автоматично підганяється під обрану тривалість ролика. GenFlik встановлюється як застосунок у Shopify і має MCP-сервер, через який відео можна створювати з Claude, Cursor чи ChatGPT. Оплата за використання, без підписки.', 'GenFlik creates ad videos in a user-generated content style for TikTok, Instagram Reels, YouTube Shorts and paid social. You can start from a product link, a text description or a few photos. The service writes the ad script, generates a realistic avatar that talks about the product, voices the text in one of 31 languages, and adds captions, background music, shots of your product photos and a branded outro. The script can be previewed and edited for free, and credits are spent only when rendering the finished MP4. There is a mode with only the product on screen and a voiceover, voice cloning, and script length automatically fits the chosen video duration. GenFlik installs as a Shopify app and has an MCP server, so videos can be created from Claude, Cursor or ChatGPT. Pay as you go, no subscription.', 'Відео з посилання на товар, опису чи фото
Автоматичний сценарій реклами
Реалістичний аватар-ведучий
Озвучення 31 мовою і клонування голосу
Субтитри, музика й кадри з фото товару
Застосунок для Shopify
MCP-сервер для Claude, Cursor і ChatGPT', 'Video from a product link, description or photos
Automatic ad script
Realistic talking avatar
Voiceover in 31 languages and voice cloning
Captions, music and product photo shots
Shopify app
MCP server for Claude, Cursor and ChatGPT', 'Власники магазинів на Shopify, дропшипери, засновники й маркетингові команди, яким потрібні відеооголошення без залучення блогерів.', 'Shopify merchants, dropshippers, founders and marketing teams who need video ads without hiring creators.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
