-- YouArt — Генерація зображень
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'youart.ai' OR LOWER(`name`) = LOWER('YouArt'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'YouArt', NULL, 'https://youart.ai', NULL, NULL, 'Платформа для генерації зображень і відео, що об''єднує багато сторонніх AI-моделей: генерація за запитом, побудова процесів на полотні, рекламні UGC-відео й десятки інструментів обробки фото та відео.', 'A platform for generating images and video that brings together many third-party AI models: prompt-based generation, canvas workflows, UGC ad videos and dozens of photo and video editing tools.', 'YouArt збирає в одному місці доступ до багатьох моделей генерації зображень і відео від різних розробників, тож не потрібно оформлювати окремі підписки на кожну. Можна просто написати запит до обраної моделі, вибудувати складніший процес створення на полотні з блоків або згенерувати рекламне відео у стилі контенту від користувачів. Окремо доступні десятки інструментів: видалення фону, вирізання об''єктів, збільшення роздільної здатності фото й відео, зміна ракурсу та освітлення, домальовування й розширення зображень, видалення водяних знаків, автоматичні субтитри, синхронізація губ, «говорячі» фото, кольорокорекція, стиснення відео тощо. Є генератори для анімації логотипів, відео товарів і навчальних роликів, а також MCP-сервер. У режимі Free Mode частина моделей працює без витрати кредитів. Для авторів передбачені партнерські програми з можливістю заробітку.', 'YouArt gathers access to many image and video generation models from different developers in one place, so you do not need a separate subscription for each. You can write a prompt for a chosen model, build a more complex creation workflow on a canvas of blocks, or generate an ad video in a user-generated content style. Dozens of tools are available separately: background removal, object cutout, photo and video upscaling, camera angle and lighting changes, inpainting and image extension, watermark removal, automatic subtitles, lip sync, talking photos, color grading, video compression and more. There are generators for logo animation, product videos and tutorial videos, as well as an MCP server. In Free Mode some models run without spending credits. Partner programs let creators earn.', 'Доступ до багатьох моделей генерації в одному сервісі
Побудова процесів на полотні з блоків
Генератор рекламних UGC-відео
Видалення фону, збільшення роздільності, домальовування
Субтитри, синхронізація губ, «говорячі» фото
Free Mode без витрати кредитів для частини моделей
MCP-сервер і партнерські програми', 'Many generation models in one service
Canvas workflows built from blocks
UGC ad video generator
Background removal, upscaling, inpainting
Subtitles, lip sync, talking photos
Free Mode with no credits for some models
MCP server and partner programs', 'Автори контенту, дизайнери, маркетологи та інтернет-магазини, яким потрібні різні генеративні моделі в одному місці.', 'Content creators, designers, marketers and online stores that need various generative models in one place.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
