SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zerotwo.ai' OR LOWER(`name`) = LOWER('ZeroTwo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ZeroTwo', NULL, 'https://zerotwo.ai', NULL, NULL, 'AI-агент і альтернатива ChatGPT для реальної роботи: отримує мету, збирає контекст, планує й виконує дії у файлах, застосунках і в інтернеті, а потім видає готовий результат. Є безкоштовний тариф.', 'An AI agent and ChatGPT alternative for real work: it takes a goal, gathers context, plans and acts across files, apps and the web, then delivers a finished result. There is a free plan.', 'ZeroTwo поєднує звичний AI-чат із агентами, які доводять завдання до кінця. Ви ставите мету, а сервіс сам збирає потрібний контекст, планує роботу, діє у ваших файлах, застосунках і в інтернеті та повертає результат, яким можна одразу користуватися: документ, дослідження чи код. У чаті доступні різні AI-моделі, генерація зображень і відео, пам''ять між розмовами, проєкти й завантаження файлів. Окремо є робочий агент для багатокрокових завдань, агент для програмування, режим глибокого дослідження та веб-пошук. Сервіс працює в браузері, а також має настільний і мобільний застосунки. Безкоштовний тариф обмежений 15 повідомленнями на день і вужчим вибором моделей; платні тарифи додають кредити, ширший вибір моделей і доступ до агентів.', 'ZeroTwo combines a familiar AI chat with agents that see tasks through. You set a goal and the service gathers the needed context, plans the work, acts across your files, apps and the web, and returns a result you can use right away: a document, research or code. The chat offers various AI models, image and video generation, memory across conversations, projects and file uploads. There is also a work agent for multi-step tasks, a coding agent, a deep research mode and web search. The service works in the browser and also has desktop and mobile apps. The free plan is limited to 15 messages a day and a narrower model choice; paid plans add credits, more models and access to agents.', 'AI-чат із вибором моделей
Агент для багатокрокових робочих завдань
Агент для програмування
Глибокі дослідження й веб-пошук
Генерація зображень і відео
Пам''ять, проєкти й завантаження файлів
Веб, настільний і мобільний застосунки', 'AI chat with a choice of models
Work agent for multi-step tasks
Coding agent
Deep research and web search
Image and video generation
Memory, projects and file uploads
Web, desktop and mobile apps', 'Професіонали й автори контенту, яким потрібен AI-помічник, що виконує завдання, а не лише відповідає.', 'Professionals and content creators who need an AI helper that completes tasks, not just answers.', 'web,desktop,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
