-- MySpec — Асистенти коду
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'myspec.dev' OR LOWER(`name`) = LOWER('MySpec'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MySpec', NULL, 'https://myspec.dev', NULL, NULL, 'AI-«архітектор» для розробки за специфікацією: розпитує вас про ідею, виявляє граничні випадки й готує набір із чотирьох файлів специфікації, за якими потім пишуть код AI-агенти в Cursor, Claude Code чи Windsurf.', 'An AI "architect" for spec-driven development: it interviews you about your idea, uncovers edge cases and prepares a four-file spec bundle that AI agents in Cursor, Claude Code or Windsurf then build from.', 'MySpec допомагає розробникам, які пишуть код за допомогою AI-агентів, почати з чіткої специфікації, а не з розмитого запиту. Сервіс проводить структуроване інтерв''ю на кшталт розмови з досвідченим архітектором: уточнює обсяг, з''ясовує граничні випадки й неочевидні вимоги. За результатами він готує набір із чотирьох файлів: принципи проєкту, вимоги з критеріями приймання, опис технічного рішення з діаграмами та план завдань. Цей набір стає єдиним джерелом правди, за яким AI-агенти в Cursor, Claude Code чи Windsurf пишуть код, що зменшує кількість вигаданих чи неточних рішень. Специфікацію можна редагувати звичайною мовою, зміни зберігаються з історією версій, а передати її агентам можна через MCP. Підходить і для нових проєктів, і для доопрацювання наявних. Зараз сервіс у відкритому бета-тестуванні.', 'MySpec helps developers who write code with AI agents start from a clear specification rather than a vague prompt. The service runs a structured interview like a conversation with a senior architect: it clarifies scope and uncovers edge cases and non-obvious requirements. From the results it prepares a bundle of four files: project principles, requirements with acceptance criteria, a technical solution with diagrams and a task plan. This bundle becomes the single source of truth from which AI agents in Cursor, Claude Code or Windsurf write code, reducing invented or inaccurate decisions. The spec can be edited in plain language, changes are kept with version history, and it can be handed to agents via MCP. It suits both new projects and work on existing ones. The service is currently in open beta.', 'Інтерв''ю для уточнення вимог
Виявлення граничних випадків
Набір із чотирьох файлів специфікації
Критерії приймання й діаграми рішення
Редагування звичайною мовою й історія версій
Передача специфікації агентам через MCP
Для нових і наявних проєктів', 'Interview to clarify requirements
Edge case discovery
Four-file specification bundle
Acceptance criteria and solution diagrams
Plain-language edits and version history
Spec handoff to agents via MCP
For new and existing projects', 'Розробники й незалежні творці, які використовують AI-агентів для написання коду.', 'Developers and indie builders who use AI agents to write code.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
