-- AppDeploy — Веб-розробка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'appdeploy.ai' OR LOWER(`name`) = LOWER('AppDeploy'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AppDeploy', NULL, 'https://appdeploy.ai', NULL, NULL, 'Сервіс публікації застосунків прямо з розмови в ChatGPT чи Claude: асистент пише код, а AppDeploy повертає в чат робоче посилання з хостингом, базою даних, авторизацією й сховищем файлів.', 'A service that deploys apps straight from a ChatGPT or Claude conversation: the assistant writes the code and AppDeploy returns a live link in the chat with hosting, database, auth and file storage.', 'AppDeploy прибирає крок, на якому зазвичай зупиняються люди, що створюють застосунки з AI-асистентами, — розгортання й хостинг. Сервіс встановлюється як доповнення до ChatGPT чи Claude: ви описуєте застосунок у чаті, асистент пише код, а AppDeploy публікує його й повертає готове посилання прямо в розмову. Не потрібно обирати хостинг чи проходити екрани налаштувань. Застосунки отримують HTTPS, бекенд, базу даних і сховище файлів, авторизацію користувачів, оновлення в реальному часі, сповіщення, вбудований AI, історію версій з можливістю відкату та завдання за розкладом. У галереї на сайті показані реальні приклади: застосунок попередніх замовлень для пекарні, браузерна гра, розподіл спільних витрат. Безкоштовний тариф має водяний знак; платний Plus додає більше кредитів, власні домени, прибирає водяний знак і пропонує автоматичну перевірку якості.', 'AppDeploy removes the step where people building apps with AI assistants usually get stuck: deployment and hosting. It installs as an add-on to ChatGPT or Claude: you describe the app in the chat, the assistant writes the code, and AppDeploy publishes it and returns a live link right in the conversation. There is no hosting to choose and no setup screens. Apps get HTTPS, a backend, a database and file storage, user authentication, real-time updates, notifications, built-in AI, version history with rollback and scheduled jobs. The gallery on the site shows real examples: a bakery pre-order app, a browser game and a shared expense splitter. The free plan has a watermark; the paid Plus plan adds credits and custom domains, removes the watermark and offers automatic QA.', 'Публікація застосунку з ChatGPT чи Claude
Робоче посилання прямо в розмові
Хостинг із HTTPS, база даних і сховище файлів
Авторизація, оновлення в реальному часі, сповіщення
Історія версій і відкат
Завдання за розкладом
Власні домени на тарифі Plus', 'Deploy an app from ChatGPT or Claude
Live link right in the conversation
Hosting with HTTPS, database and file storage
Auth, real-time updates and notifications
Version history and rollback
Scheduled jobs
Custom domains on the Plus plan', 'Люди будь-якого рівня, які створюють застосунки з допомогою AI-асистентів і хочуть швидко опублікувати їх.', 'People of any skill level who build apps with AI assistants and want to publish them quickly.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
