SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'choosaro.com' OR LOWER(`name`) = LOWER('Choosaro'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Choosaro', NULL, 'https://choosaro.com', NULL, NULL, 'AI-сервіс для порівняння варіантів і ухвалення рішень: опишіть, що обираєте, додайте варіанти текстом чи зображеннями — і отримаєте оцінку кожного від 0 до 100, розбір за критеріями та пояснення, чому лідирує саме він.', 'An AI service for comparing options and making decisions: describe what you are choosing, add options as text or images, and get a 0–100 score for each, a per-criteria breakdown and an explanation of why the leader comes out on top.', 'Choosaro допомагає швидше ухвалювати рішення, коли варіантів кілька, а впевненості бракує. Спершу ви звичайними словами описуєте, що саме обираєте, наприклад, яку з кількох назв дати відео, і за потреби додаєте зображення для контексту та мову відповіді. Потім додаєте варіанти — текстом, зображеннями або їх поєднанням, — а AI аналізує їх поруч. У результаті кожен варіант отримує оцінку від 0 до 100, розбір за окремими критеріями з поясненнями, рівень упевненості AI, обґрунтування вибору лідера й поради щодо наступних кроків. Сервіс підходить для ідей, контенту, продуктових рішень і повсякденних виборів. Підписка не продовжується автоматично: план купується на потрібний строк і поновлюється вручну. Безкоштовний тариф дає 15 порівнянь на місяць; є застосунок для iOS.', 'Choosaro helps you decide faster when there are several options and not enough confidence. First you describe in plain words what you are choosing, for example which of several titles to give a video, and optionally add images for context and pick the answer language. Then you add the options as text, images or both, and the AI analyzes them side by side. Each option gets a score from 0 to 100, a per-criteria breakdown with explanations, the AI''s confidence level, the reasoning behind the leading option and suggestions for next steps. It works for ideas, content, product decisions and everyday choices. Plans do not renew automatically: you buy a plan for the period you need and renew it manually. The free plan gives 15 comparisons a month; there is an iOS app.', 'Порівняння варіантів текстом, зображеннями чи разом
Оцінка кожного варіанта від 0 до 100
