-- AirMusic — Музика
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'airmusic.ai' OR LOWER(`name`) = LOWER('AirMusic'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AirMusic', NULL, 'https://airmusic.ai', NULL, NULL, 'AI-генератор музики: створює оригінальні пісні з текстового опису чи власних слів у вибраному стилі й з вокалом, а також кліпи, кавери, інструментали, подовження треків і додавання вокалу до мінусовок.', 'An AI music generator: it creates original songs from a text description or your own lyrics in a chosen style and with vocals, plus music videos, covers, instrumentals, track extensions and vocals for backing tracks.', 'AirMusic дає змогу створити пісню без музичної освіти. Достатньо описати бажану композицію або вставити власний текст, обрати стиль, тип вокалу й модель — і сервіс згенерує завершений трек, який можна прослухати й завантажити у форматі MP3 чи WAV. Коли аудіо готове, з нього можна зробити музичне відео. Набір додаткових інструментів включає подовження треку зі збереженням стилю й настрою, кавери з іншими вокальними стилями, додавання AI-вокалу до інструменталу за вашим текстом, створення інструменталів і мінусовок, ремікси, генерацію текстів пісень, клонування голосу, нарізку аудіо й аналіз музики. Безкоштовний тариф дає невелику кількість кредитів і тимчасове зберігання; платні плани додають більше пісень, приватну генерацію, паралельні завдання й комерційну ліцензію. Також можна купити разовий пакет кредитів.', 'AirMusic lets you create a song without musical training. Describe the composition you want or paste your own lyrics, choose a style, vocal type and model, and the service generates a finished track you can preview and download as MP3 or WAV. Once the audio is ready, you can turn it into a music video. Extra tools include extending a track while keeping its style and mood, covers with other vocal styles, adding AI vocals to an instrumental from your lyrics, creating instrumentals and backing tracks, remixes, lyric generation, voice cloning, audio cutting and music analysis. The free plan gives a small number of credits and temporary storage; paid plans add more songs, private generation, parallel tasks and a commercial license. A one-time credit pack is also available.', 'Пісні з текстового опису чи власних слів
Вибір стилю, вокалу й моделі
Генератор музичних відео
Подовження треків і кавери
Додавання вокалу до інструменталу
Інструментали, ремікси й генерація текстів
Клонування голосу й аналіз музики', 'Songs from a text description or your own lyrics
Choice of style, vocals and model
Music video generator
Track extension and covers
Adding vocals to an instrumental
Instrumentals, remixes and lyric generation
Voice cloning and music analysis', 'Музиканти-аматори, автори контенту й усі, хто хоче швидко створити оригінальну пісню чи фонову музику.', 'Hobby musicians, content creators and anyone who wants to quickly create an original song or background music.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
