-- CorpusIQ — Аналітика
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'corpusiq.io' OR LOWER(`name`) = LOWER('CorpusIQ'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'CorpusIQ', NULL, 'https://corpusiq.io', NULL, NULL, 'Сервіс, що підключає ChatGPT, Claude чи Perplexity до ваших бізнес-систем: ставте запитання про продажі, рекламу чи гроші звичайними словами й отримуйте відповідь із дашбордом і посиланнями на джерело кожної цифри.', 'A service that connects ChatGPT, Claude or Perplexity to your business systems: ask about sales, ads or cash in plain words and get an answer with a dashboard and a source for every number.', 'CorpusIQ дає AI-асистентам доступ до реальних даних вашого бізнесу. Після підключення інструментів — наприклад магазину на Shopify чи бухгалтерії в QuickBooks, загалом понад 40 конекторів — можна прямо в ChatGPT, Claude або Perplexity запитати, якою була виручка минулого місяця чи як працює реклама. CorpusIQ читає дані з підключених систем і повертає пряму відповідь у вигляді дашборду з графіками й цифрами, порахованими за вашими правилами, наприклад замовлення за вирахуванням повернень. Будь-яке число можна натиснути й побачити, з якого джерела воно взяте. Доступ до зовнішніх систем лише на читання, дані клієнтів не використовуються для навчання моделей, є MCP-сервер. Тарифи відрізняються кількістю користувачів, усі включають повний набір конекторів. Є 30-денний безкоштовний пробний період без картки й демо на прикладі вигаданої компанії.', 'CorpusIQ gives AI assistants access to your real business data. After you connect your tools, such as a Shopify store or QuickBooks accounting, with more than 40 connectors in total, you can ask right in ChatGPT, Claude or Perplexity what last month''s revenue was or how ads are performing. CorpusIQ reads data from the connected systems and returns a direct answer as a dashboard with charts and numbers counted by your rules, for example orders minus refunds. You can tap any number and see which source it came from. Access to external systems is read-only, customer data is not used to train models, and there is an MCP server. Plans differ in the number of users and all include the full set of connectors. There is a 30-day free trial with no card and a demo on a sample company.', 'Запитання про бізнес у ChatGPT, Claude і Perplexity
Понад 40 конекторів до бізнес-систем
Відповіді з дашбордами й графіками
Джерело кожної цифри одним дотиком
Підрахунок за вашими правилами
Доступ лише на читання
MCP-сервер', 'Business questions in ChatGPT, Claude and Perplexity
40+ connectors to business systems
Answers with dashboards and charts
Source of every number in one tap
Counting by your own rules
Read-only access
MCP server', 'Власники й керівники малого та середнього бізнесу, які хочуть отримувати точні відповіді про свої показники без ручних звітів.', 'Owners and managers of small and mid-sized businesses who want accurate answers about their metrics without manual reports.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
