INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'CorpusIQ gives AI assistants access to your real business data. After you connect your tools, such as a Shopify store or QuickBooks accounting, with more than 40 connectors in total, you can ask right in ChatGPT, Claude or Perplexity what last month''s revenue was or how ads are performing. CorpusIQ reads data from the connected systems and returns a direct answer as a dashboard with charts and numbers counted by your rules, for example orders minus refunds. You can tap any number and see which source it came from. Access to external systems is read-only, customer data is not used to train models, and there is an MCP server. Plans differ in the number of users and all include the full set of connectors. There is a 30-day free trial with no card and a demo on a sample company.', 'manual' FROM DUAL WHERE @new = 1;
