-- Adviserry — Планування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'adviserry.com' OR LOWER(`name`) = LOWER('Adviserry'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Adviserry', NULL, 'https://adviserry.com', NULL, NULL, 'Сервіс для засновників, що читає розсилки й YouTube-відео експертів, на яких ви підписані, зіставляє їх із вашим проєктом і щотижня готує список конкретних дій, вартих уваги.', 'A service for founders that reads the newsletters and YouTube videos of the experts you follow, weighs them against your project and each week prepares a list of specific actions worth taking.', 'Adviserry розв''язує знайому проблему: ви підписані на розсилки й канали сильних експертів, але рідко встигаєте застосувати прочитане. Сервіс читає все, що публікують обрані вами автори — розсилки та відео на YouTube, — а також ваші власні документи, як-от презентації для інвесторів, стратегії, бізнес-плани й дослідження ринку. Він зважує нові ідеї з огляду на те, над чим ви зараз працюєте, і щотижня складає чернетки конкретних кроків: наприклад, як підняти ціни без втрати клієнтів, з посиланнями на авторів, з чиїх матеріалів зроблено висновок. Остаточне рішення завжди за вами. Доступ до пошти й документів лише на читання: сервіс нічого не надсилає, не видаляє й не передає, а доступ можна відкликати будь-коли. На сайті є інтерактивне демо й безкоштовний приклад плану дій у PDF.', 'Adviserry solves a familiar problem: you subscribe to newsletters and channels from strong experts but rarely get to apply what you read. The service reads everything your chosen authors publish, newsletters and YouTube videos, as well as your own documents such as pitch decks, strategies, business plans and market research. It weighs new ideas against what you are working on now and each week drafts specific moves, for example how to raise prices without losing customers, with links to the authors whose material led to the conclusion. The final decision is always yours. Access to email and documents is read-only: the service never sends, deletes or shares anything, and access can be revoked at any time. The site has an interactive demo and a free sample action plan in PDF.', 'Читання розсилок і YouTube-відео обраних експертів
Урахування ваших документів і поточних завдань
Щотижневий список конкретних дій
Посилання на джерела кожної поради
Доступ лише на читання з можливістю відкликання
Інтерактивне демо без реєстрації', 'Reads newsletters and YouTube videos of chosen experts
Takes your documents and current work into account
Weekly list of specific actions
Source links for every recommendation
Read-only access that can be revoked
Interactive demo without sign-up', 'Засновники стартапів і підприємці, які стежать за експертами, але хочуть системно застосовувати їхні поради.', 'Startup founders and entrepreneurs who follow experts but want to apply their advice systematically.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
