-- AIWriteBook — Публікації
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aiwritebook.com' OR LOWER(`name`) = LOWER('AIWriteBook'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'AIWriteBook', NULL, 'https://aiwritebook.com', NULL, NULL, 'AI-інструмент для авторів книжок: від ідеї чи нотаток до плану, персонажів і розділів, написаних вашим стилем, з обкладинками, ілюстраціями, аудіокнигою та експортом, готовим до Amazon KDP.', 'An AI tool for book authors: from an idea or notes to an outline, characters and chapters written in your voice, with covers, illustrations, an audiobook and export ready for Amazon KDP.', 'AIWriteBook проводить автора через усі етапи роботи над книжкою. Почати можна з ідеї, власних нотаток або імпорту чернетки з Word. Сервіс допомагає створити персонажів, план книжки й кожного розділу, а також налаштувати стиль письма, щоб AI навчився писати вашим голосом. Далі він пише розділи, перевіряє граматику й стиль, а окремий чат-помічник допомагає з кожним розділом. Для оформлення доступні AI-обкладинки й ілюстрації до розділів, верстка й генерація аудіокниги. Готові файли можна експортувати у форматах і розмірах, потрібних для публікації на Amazon KDP та KDP Print, а також у DOCX; книжку можна опублікувати на платформі NanoReads. Підтримується понад 20 жанрів і понад 30 мов. Безкоштовно доступні повний план книжки й перший розділ; платні тарифи працюють на кредитах, є щомісячна, річна та разова оплата.', 'AIWriteBook guides an author through every stage of working on a book. You can start from an idea, your own notes or a draft imported from Word. The service helps create characters, a book outline and an outline for each chapter, and set up a writing style so the AI learns to write in your voice. It then writes chapters and checks grammar and style, and a chat assistant helps with each chapter. For the finishing touches there are AI covers and chapter illustrations, formatting and audiobook generation. Finished files can be exported in the formats and sizes needed for Amazon KDP and KDP Print, as well as DOCX, and the book can be published on the NanoReads platform. More than 20 genres and more than 30 languages are supported. A full book outline and the first chapter are free; paid plans run on credits, with monthly, yearly and one-time billing.', 'План книжки й розділів з ідеї чи нотаток
Конструктор персонажів
Навчання на вашому стилі письма
Написання розділів і перевірка граматики
AI-обкладинки, ілюстрації та аудіокниги
Експорт для Amazon KDP, KDP Print і DOCX
Імпорт чернетки з Word, понад 30 мов', 'Book and chapter outline from an idea or notes
Character builder
Learns your writing style
Chapter writing and grammar check
AI covers, illustrations and audiobooks
Export for Amazon KDP, KDP Print and DOCX
Word draft import, 30+ languages', 'Автори художньої й нехудожньої літератури, які хочуть дописати й опублікувати книжку, зокрема через Amazon KDP.', 'Fiction and nonfiction authors who want to finish and publish a book, including through Amazon KDP.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-02 00:00:00' FROM DUAL WHERE @new = 1;
