-- Collate — Нотатки та організація
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'collate.one' OR LOWER(`name`) = LOWER('Collate'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Collate', NULL, 'https://collate.one', NULL, NULL, 'Безкоштовний застосунок для Mac для роботи з PDF за допомогою AI: чат із документом чи цілою папкою, стислі підсумки й посилання на конкретну сторінку. Локальна модель працює на вашому комп''ютері без хмари.', 'A free Mac app for working with PDFs using AI: chat with a document or a whole folder, concise summaries and links to the exact page. The local model runs on your computer without the cloud.', 'Collate — нативний застосунок для macOS, який допомагає читати й розуміти PDF-документи, не передаючи їх у хмару. Можна поставити запитання до одного документа чи цілої папки й отримати відповідь, що спирається на текст, швидко побачити стислий підсумок довгого документа перед уважним читанням і перейти за посиланням до точної сторінки, звідки взято відповідь. Також є виділення, впорядкування й експорт матеріалів. У режимі локального AI модель завантажується один раз і працює прямо на Mac, тож вміст документів не надсилається постачальникам хмарних моделей. За бажанням можна підключити хмарну модель за власним ключем, і застосунок завжди показує, який режим увімкнено. Обліковий запис Collate не потрібен. Потрібна macOS 13.5 або новіша.', 'Collate is a native macOS app that helps you read and understand PDF documents without sending them to the cloud. You can ask a question about one document or a whole folder and get an answer grounded in the text, quickly see a summary of a long document before reading closely, and follow a link to the exact page the answer came from. Highlighting, organizing and exporting are also available. In Local AI mode the model is downloaded once and runs right on the Mac, so document content is not sent to cloud model providers. If you prefer, you can connect a cloud model with your own key, and the app always shows which mode is on. No Collate account is required. macOS 13.5 or later is needed.', 'Чат з одним PDF чи цілою папкою
Стислі підсумки довгих документів
Посилання на точну сторінку джерела
Локальний AI без передачі документів у хмару
