SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'collate.one' OR LOWER(`name`) = LOWER('Collate')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'text-chatbots' LIMIT 1;
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'finance-legal' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'text-chatbots' AND s.`slug` = 'notes' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'finance-legal' AND s.`slug` = 'documents' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'A free Mac app for working with PDFs using AI: chat with a document or a whole folder, concise summaries and links to the exact page. The local model runs on your computer without the cloud.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Collate is a native macOS app that helps you read and understand PDF documents without sending them to the cloud. You can ask a question about one document or a whole folder and get an answer grounded in the text, quickly see a summary of a long document before reading closely, and follow a link to the exact page the answer came from. Highlighting, organizing and exporting are also available. In Local AI mode the model is downloaded once and runs right on the Mac, so document content is not sent to cloud model providers. If you prefer, you can connect a cloud model with your own key, and the app always shows which mode is on. No Collate account is required. macOS 13.5 or later is needed.', 'manual' FROM DUAL WHERE @new = 1;
